-- shitaro no-key boot wrapper
local function __shitaro_show_err(err)
	warn("[shitaro] ERROR:", tostring(err))
	warn(debug.traceback(tostring(err), 2))
	pcall(function()
		local cg = game:GetService("CoreGui")
		local sg = Instance.new("ScreenGui")
		sg.Name = "ShitaroBootError"
		sg.ResetOnSpawn = false
		sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		pcall(function() sg.Parent = cg end)
		if not sg.Parent then
			local lp = game:GetService("Players").LocalPlayer
			if lp then sg.Parent = lp:WaitForChild("PlayerGui") end
		end
		local fr = Instance.new("Frame")
		fr.Size = UDim2.fromOffset(520, 160)
		fr.Position = UDim2.new(0.5, -260, 0.12, 0)
		fr.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
		fr.BorderSizePixel = 0
		fr.Parent = sg
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1
		t.Size = UDim2.new(1, -16, 1, -16)
		t.Position = UDim2.fromOffset(8, 8)
		t.Font = Enum.Font.Code
		t.TextSize = 14
		t.TextColor3 = Color3.fromRGB(255, 90, 90)
		t.TextXAlignment = Enum.TextXAlignment.Left
		t.TextYAlignment = Enum.TextYAlignment.Top
		t.TextWrapped = true
		t.Text = "SHITARO ERROR:\n" .. tostring(err)
		t.Parent = fr
	end)
end

