local function __safe_global(name)
	local ok, val = pcall(function()
		return rawget(getfenv and getfenv() or _G, name)
	end)
	if ok then return val end
	ok, val = pcall(function()
		return (getgenv and getgenv() or _G)[name]
	end)
	return ok and val or nil
end

local shhttp = (type(__safe_global("request")) == "function" and __safe_global("request"))
	or (syn and syn.request)
	or (http and http.request)
	or (fluxus and fluxus.request)
	or (getgenv and type(getgenv().request) == "function" and getgenv().request)
	or (type(__safe_global("http_request")) == "function" and __safe_global("http_request"))

if type(shhttp) ~= "function" then
	-- fallback to game:HttpGet-style wrapper
	shhttp = function(opts)
		if type(opts) ~= "table" or type(opts.Url) ~= "string" then
			return nil
		end
		local ok, body = pcall(function()
			return game:HttpGet(opts.Url)
		end)
		if ok and type(body) == "string" then
			return { StatusCode = 200, Body = body, Headers = {} }
		end
		return nil
	end
	print("[shitaro] using HttpGet fallback for requests")
else
	print("[shitaro] http request function found")
end

