local function __b64decode(data)
	local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local t = {}
	for i = 1, #b do t[string.byte(b, i)] = i - 1 end
	data = string.gsub(data, "[^A-Za-z0-9+/=]", "")
	local out = {}
	local n = 0
	local i = 1
	while i <= #data do
		local a = t[string.byte(data, i)] or 0
		local b2 = t[string.byte(data, i + 1)] or 0
		local c = t[string.byte(data, i + 2)] or 0
		local d = t[string.byte(data, i + 3)] or 0
		local n32 = a * 262144 + b2 * 4096 + c * 64 + d
		n = n + 1; out[n] = string.char(math.floor(n32 / 65536) % 256)
		if string.sub(data, i + 2, i + 2) ~= "=" then
			n = n + 1; out[n] = string.char(math.floor(n32 / 256) % 256)
		end
		if string.sub(data, i + 3, i + 3) ~= "=" then
			n = n + 1; out[n] = string.char(n32 % 256)
		end
		i = i + 4
	end
	return table.concat(out)
end

local esp = nil
local lib = nil
local prevLib = getgenv().shitaroebet

if prevLib then
	pcall(function()
		prevLib:unload()
	end)

	getgenv().shitaroebet = nil
end
do
	local function libsrc(name)
		-- 1) embedded offline payload
		local emb = __SHITARO_EMBED and __SHITARO_EMBED[name]
		if type(emb) == "string" and #emb > 0 then
			local ok, body = pcall(__b64decode, emb)
			if ok and type(body) == "string" and #body > 0 then
				print("[shitaro] loaded embedded:", name, #body)
				-- cache to disk for faster next inject / debugging
				pcall(function()
					if type(writefile) == "function" then
						writefile(name, body)
					end
				end)
				return body
			else
				warn("[shitaro] b64 decode failed for", name, tostring(body))
			end
		else
			print("[shitaro] no embed for", name, type(emb))
		end

		-- 2) local file on disk
		local ok_is, has = pcall(isfile, name)

		if ok_is and has then
			local ok_rd, body = pcall(readfile, name)

			if ok_rd and type(body) == "string" and #body > 0 then
				print("[shitaro] loaded local:", name, #body)
				return body
			end
		end

		print("[shitaro] downloading:", name)
		for attempt = 1, 3 do
			local ok, body = pcall(shnet.lib, name)

			if ok and type(body) == "string" and #body > 0 then
				print("[shitaro] downloaded:", name, #body)
				return body
			end

			print("[shitaro] download failed:", name, "attempt", attempt, "err:", tostring(body))
			task.wait(0.75)
		end

		return nil
	end

	
	-- key stubs so protected UI does not early-exit
	getgenv().SHKEY = getgenv().SHKEY or { alive = true, value = "nokey", stop = function() end, bind = function() end }
	getgenv().SCRIPT_KEY = getgenv().SCRIPT_KEY or "nokey"
	getgenv().JD_IS_PREMIUM = true
	getgenv().JD_REASON = "KEY_VALID"

	local espSrc = libsrc("esp.lua")
	local uiSrc = libsrc("shitaroebet.lua")

	if not espSrc then
		warn("[shitaro] FAILED: could not load esp.lua (network / signature / http)")
	end
	if not uiSrc then
		warn("[shitaro] FAILED: could not load shitaroebet.lua (network / signature / http)")
	end

	if espSrc and uiSrc then
		local espLoad, espErr = loadstring(espSrc, "@esp")
		local uiLoad, uiErr = loadstring(uiSrc, "@shitaroebet")
		espSrc, uiSrc = nil, nil

		if not espLoad then
			warn("[shitaro] FAILED loadstring esp:", tostring(espErr))
		end
		if not uiLoad then
			warn("[shitaro] FAILED loadstring ui:", tostring(uiErr))
		end

		if espLoad and uiLoad then
			local ok1, r1 = pcall(espLoad)

			if ok1 then
				esp = r1
				print("[shitaro] esp ok")
			else
				warn("[shitaro] FAILED run esp:", tostring(r1))
			end

			local ok2, r2 = pcall(uiLoad)

			if ok2 then
				lib = r2
				print("[shitaro] ui ok, type=", type(lib))
				if type(lib) == "table" then
					local keys = {}
					for k, v in pairs(lib) do
						keys[#keys + 1] = tostring(k) .. ":" .. type(v)
					end
					table.sort(keys)
					print("[shitaro] lib keys:", table.concat(keys, ", "))
				end
			else
				warn("[shitaro] FAILED run ui:", tostring(r2))
			end
		end
	end
end

if type(lib) ~= "table" or type(lib.window) ~= "function" then
	warn("[shitaro] FATAL: UI library not loaded — script stopped. Check console above.")
	pcall(function()
		local sg = Instance.new("ScreenGui")
		sg.Name = "ShitaroError"
		sg.ResetOnSpawn = false
		pcall(function() sg.Parent = game:GetService("CoreGui") end)
		if not sg.Parent then sg.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui") end
		local fr = Instance.new("Frame")
		fr.Size = UDim2.fromOffset(420, 90)
		fr.Position = UDim2.new(0.5, -210, 0.15, 0)
		fr.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
		fr.BorderSizePixel = 0
		fr.Parent = sg
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1
		t.Size = UDim2.fromScale(1, 1)
		t.Font = Enum.Font.GothamBold
		t.TextSize = 16
		t.TextColor3 = Color3.fromRGB(255, 80, 80)
		t.TextWrapped = true
		t.Text = "SHITARO: failed to load UI library\n(esp.lua / shitaroebet.lua)\nCheck F9 console for [shitaro] logs"
		t.Parent = fr
		task.delay(12, function() pcall(function() sg:Destroy() end) end)
	end)
	return
end

