			ToolTip = "Catches pixel ledges and map seams, then slides along them like surf",
			Default = false,
			Flag = "PixelSurf",
			Option = true,
			Callback = function(v)
				surf_on = v
				if not v then surf_hide() end
			end
		})

		surf.Option:AddSlider({
			Name = "speed",
			Default = 34,
			Min = 8,
			Max = 90,
			Round = 0,
			Flag = "misc_surf_speed",
			Callback = function(v)
				surf_speed = v
			end
		})
	end)

